def compute(vars):
    berths = vars["v1"]
    ships = vars["v2"]

    if ships == 0:
        return None

    value = berths / ships

    return {
        "value": value,
        "trace": {
            "berths": berths,
            "ships": ships,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "berths per ship"
            }
        }
    }
